exit 37 1 J-02 from_J10
exit 38 1 J-02 from_J10
mark from_J02 37 3 S
mark from_J09 2 3 S
flood 8 2 23 5 cond="UQ09_FLOOD == 1"
flood 1 7 30 11 cond="UQ09_FLOOD == 1"
# ---------------------------------------------------------------- 동쪽 높은 턱 · 사다리
text 35 4 "바닥에 분필 화살표. '여기까지 — 민지'. 화살표 끝이 저수조 쪽을 가리킨다. 분필이 아직 덜 번졌다." w=1
text 33 2 "철판 당번표가 벽에 볼트로 박혔다. '상인회 배수 청소 당번 2194 — 1조 · 2조 · 3조 · 4조'. 1조~3조 칸에 날짜 도장. 4조 칸은 비었다." w=1
# ---------------------------------------------------------------- 필터 저수조 · 흡입관 · 배수 밸브
prop reservoir 17 2
text 19 3 "필터 저수조." w=3 scene=UQ09_TANK
prop pipe_run 22 2
# 돌진 흔적(1-13k 재미 검수 ② — 지형이 '박게 하는 자리'를 말한다): 저수조 옆면 · 남쪽 벽
text 20 5 "저수조 옆면, 무릎 높이에 움푹 팬 자국이 여럿. 갈색 껍질 조각이 박혀 있다." w=1
text 12 16 "벽 아래가 움푹움푹 패었다. 껍질 조각이 박혔다 — 큰 놈이 여러 번 들이받았다." w=1
prop ds_valve 17 6 cond="UQ09_FLOOD == 0"
prop ds_valve 17 6 state=open cond="UQ09_FLOOD != 0"
text 17 6 "배수 밸브 단말." scene=UQ09_VALVE
# ---------------------------------------------------------------- 알집 셋
prop egg_cluster 14 5 cond="UQ09_E1 == 0"
prop egg_cluster 14 5 state=burnt cond="UQ09_E1 == 1"
prop egg_cluster 14 5 state=drowned cond="UQ09_E1 >= 2"
text 14 5 "알집 무더기." scene=UQ09_EGG1
prop egg_cluster 21 14 cond="UQ09_E2 == 0"
prop egg_cluster 21 14 state=burnt cond="UQ09_E2 == 1"
prop egg_cluster 21 14 state=drowned cond="UQ09_E2 >= 2"
text 21 14 "알집 무더기." scene=UQ09_EGG2
prop egg_cluster 5 4 cond="UQ09_E3 == 0"
prop egg_cluster 5 4 state=burnt cond="UQ09_E3 == 1"
prop egg_cluster 5 4 state=drowned cond="UQ09_E3 == 3"
text 5 4 "알집 무더기." scene=UQ09_EGG3
# ---------------------------------------------------------------- 물길 · 허물 길
text 26 10 "물길. 기름 같은 막이 무지개 빛으로 돈다. 물 밑에 바퀴 허물이 깔렸다." w=1 scene=UQ09_WATER
text 10 13 "바퀴 허물이 한 줄로 이어진다. 크다 — 손바닥 둘만 하다. 줄은 서쪽 벽 아래 틈으로 사라진다." w=1
text 1 16 "벽 아래 틈. 허물이 여기서 끝난다. 틈 안쪽에서 바람이 올라온다." w=1 scene=UQ09_CRACK
# ---------------------------------------------------------------- 서쪽 높은 턱 — 2194 당번 4조
prop w_ladder 2 0
text 2 2 "사다리 위 배수구 철창. 안쪽에서 사슬로 감겼다." scene=UQ09_CHAIN
prop remains 4 3
text 4 3 "유해 셋이 서로 기대 앉았다. 상인회 완장." scene=UQ09_CREW
prop drum 6 2
text 6 2 "그을린 등유 통. 바닥에 검게 탄 자국이 둥글게 번졌다 — 여기서 뭔가를 태우려 했다." w=1
# ---------------------------------------------------------------- 2077 관리원 대피 칸
prop cot 37 14
prop hm_shelf 33 13
box 33 13 stash name="물 안 닿는 선반"
text 34 14 "선반 다리에 페인트 눈금 — 2077년 침수 높이. 선반 맨 위는 눈금보다 한 뼘 높다. 여기 둔 것은 젖지 않는다." w=1
prop note_ground 35 16
text 35 16 "관리원 근무 일지." scene=UQ09_LOG
